[pre]

; ------------ --------- --------- --------- --------- --------- -

; Screen interrupt

SCRINT: PUSH AF

LD A,(INTLINE)    ; INTLINE is a variable to keep track of where the last 

scan line interrupt happened

CP COLBRK1

LD A,COLBRK2    ; COLBRK2 is a constant for the 2nd line to interrupt on

JR Z,SKP1

LD A,COLBRK1    ; COLBRK1 is a constant for the 1st line to interrupt on

SKP1 LD (INTLINE),A ; keep track of current interrupt scanline

OUT (INLIN),A ; ($0f)

; set color ( just doing left side) based on which part of the screen we are 

now

LD A,TOPCOL1    ; TOPCOL1 is a constant for the 1st color

JR Z,SKP2

LD A,BOTCOL1    ; BOTCOL1 is a ocnstant for the 2nd color

SKP2 OUT (COL0L),A ; Left Color Register 0

POP AF

RET

[/pre]

